const E=R.e,I=R.icon;
Object.assign(R.paths,{board:'M3 4h18v16H3zm6 0v16m6-16v16',gallery:'M3 3h18v18H3zm0 12 5-5 5 5 3-3 5 5M8 7h.01',up:'m6 15 6-6 6 6',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',spark:'m12 3 2 6 7 3-7 2-2 7-2-7-7-2 7-3z',menu:'M4 6h16M4 12h16M4 18h16'});
R.btn=(text,action,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
R.newButton=(text='Leave a note',extra='')=>R.btn(`${I('plus')}${text}`,'new','button primary',extra);
R.logo=()=>`<button class="logo" data-action="home" aria-label="Relay home"><span class="logo-mark"><i></i><i></i></span>relay<span>.</span></button>`;
R.projectMark=p=>`<span class="project-initial" style="--project-color:${/^#[a-f\d]{6}$/i.test(R.data.projectDetails[p]?.color)?R.data.projectDetails[p].color:'#bcd3a7'}">${E(p.slice(0,1))}</span>`;
R.projectOptions=selected=>R.data.projects.map(p=>`<option ${p===selected?'selected':''} value="${E(p)}">${E(p)}</option>`).join('');
R.projectSelect=()=>`<label class="project-picker">${R.projectMark(R.ui.project)}<select data-project-select aria-label="Your project">${R.projectOptions(R.ui.project)}<option value="__new_project__">+ Make another project</option></select>${I('down')}</label>`;
R.folderCount=id=>R.data.cards.filter(c=>!c.archived&&R.descendants(id).has(c.folder)).length;
R.folderTree=(parent='',depth=0)=>R.data.folders.filter(f=>f.project===R.ui.project&&f.parent===parent).map(f=>{const children=R.data.folders.some(x=>x.parent===f.id),closed=R.ui.collapsed.has(f.id);return `<div class="tree-branch"><div class="tree-row ${R.ui.folder===f.id?'active':''}" style="--depth:${depth}">${children?`<button class="tree-toggle ${closed?'closed':''}" data-collapse="${E(f.id)}" aria-expanded="${!closed}" aria-label="${closed?'Expand':'Collapse'} ${E(f.name)}">${I('down')}</button>`:'<span class="tree-spacer"></span>'}<button data-folder="${E(f.id)}">${I('folder')}<span>${E(f.name)}</span><small>${R.folderCount(f.id)}</small></button></div>${!closed?R.folderTree(f.id,depth+1):''}</div>`;}).join('');
R.sidebar=()=>`<aside class="workspace-sidebar ${R.ui.sideOpen?'open':''}" ${innerWidth<=760&&!R.ui.sideOpen?'inert aria-hidden="true"':''}><div class="side-brand">${R.logo()}${R.btn(I('close'),'close-sidebar','icon-button mobile-only','aria-label="Close navigation"')}</div>${R.projectSelect()}<div class="side-links">${[['all','grid','Everything'],['saved','pin','Kept close'],['archive','archive','Put aside']].map(([key,ico,label])=>`<button data-scope="${key}" class="${R.ui.scope===key&&!R.ui.folder?'active':''}">${I(ico)}<span>${label}</span>${key==='saved'?`<small>${R.data.cards.filter(c=>c.project===R.ui.project&&c.saved&&!c.archived).length}</small>`:''}</button>`).join('')}</div><div class="side-section">YOUR FOLDERS${R.btn(I('plus'),'new-folder','icon-button','aria-label="Add a folder"')}</div><nav class="folder-tree" aria-label="Your folders">${R.folderTree()||'<p class="tree-empty">A few places for your thoughts.<br>Add a folder when you need one.</p>'}</nav><button class="side-add" data-action="new-folder">${I('plus')}New folder</button><div class="sidebar-bottom">${R.newButton()}<button data-action="search">${I('search')}Find a thought<kbd>⌘ K</kbd></button><button data-action="customize">${I('settings')}Make it yours</button><div class="sidebar-foot"><span class="local-indicator"></span><span>Yours, in this browser.</span>${R.btn(I('info'),'research','icon-button','aria-label="The thinking behind Relay"')}</div></div></aside>`;
R.search=(placeholder='Find a thought…')=>`<label class="search-field">${I('search')}<input data-search aria-label="Search your notes" value="${E(R.ui.query)}" placeholder="${placeholder}"><kbd>/</kbd></label>`;
R.header=()=>`<header class="workspace-header"><div class="header-path">${R.btn(I('menu'),'toggle-sidebar','icon-button mobile-only','aria-label="Open navigation"')}<button data-action="root">${E(R.ui.project)}</button>${R.trail(R.ui.folder).map(f=>`<span>/</span><button data-folder="${E(f.id)}">${E(f.name)}</button>`).join('')}</div><div class="header-tools">${R.search()}${R.btn(I('settings'),'customize','icon-button','aria-label="Make this workspace yours"')}</div></header>`;
R.bookmark=c=>`<button class="icon-button keep-button ${c.saved?'kept':''}" data-bookmark="${E(c.id)}" aria-label="${c.saved?'Unpin':'Keep close'} ${E(c.title)}" aria-pressed="${!!c.saved}">${I('pin')}</button>`;
R.stage=c=>{const col=R.data.columns.find(x=>x.id===c.status)||R.data.columns[0];return `<span class="stage" style="--stage-color:${/^#[a-f\d]{6}$/i.test(col.color)?col.color:'#a9bda0'}"><i></i>${E(col.name)}</span>`;};
R.noteExcerpt=c=>(c.body||R.next(c)||c.tried||'A thought waiting to unfold.').replace(/\n+/g,' ');
R.noteTags=c=>(c.tags||[]).slice(0,2).map(t=>`<span class="note-tag">${E(t)}</span>`).join('');
R.empty=(title='A little room to begin.',description='A sentence, a question, a messy thought. Start anywhere.')=>`<div class="empty"><span>${I('spark')}</span><h3>${title}</h3><p>${description}</p>${R.newButton('Leave the first note')}</div>`;
R.folderCards=()=>R.childFolders().length?`<section class="folder-section"><div class="section-line"><h2>${R.ui.folder?'A little further in':'Your little corners'}</h2>${R.btn(`${I('plus')}New folder`,'new-folder','quiet-button')}</div><div class="folder-cards">${R.childFolders().map((f,i)=>`<article class="folder-card folder-color-${i%4}"><button class="folder-open" data-folder="${E(f.id)}"><div class="folder-visual">${I('folder')}<span>${R.folderCount(f.id)} ${R.folderCount(f.id)===1?'note':'notes'}</span></div><h3>${E(f.name)}</h3><p>${E(f.description||'A little space to make your own.')}</p></button>${R.btn(I('more'),'folder-options','folder-menu icon-button',`data-id="${E(f.id)}" aria-label="Options for ${E(f.name)}"`)}</article>`).join('')}</div></section>`:'';
R.viewPicker=()=>`<div class="view-picker" role="group" aria-label="How to see your notes">${[['list','lines','List'],['gallery','gallery','Cards'],['board','board','Board']].map(([key,ico,label])=>`<button data-view="${key}" class="${R.view()===key?'active':''}" aria-pressed="${R.view()===key}">${I(ico)}<span>${label}</span></button>`).join('')}</div>`;
R.collectionHeader=(label='Notes, just as you left them')=>`<div class="collection-header"><h2>${label}<small>${R.cards().length}</small></h2><div>${R.ui.folder?`<label class="nested-choice"><input type="checkbox" data-nested ${R.ui.includeNested?'checked':''}>Include little corners</label>`:''}${R.viewPicker()}</div></div>`;
R.list=cards=>cards.length?`<div class="note-list">${cards.map(c=>`<article class="note-row"><button class="note-row-open" data-open="${E(c.id)}"><span class="note-row-icon">${I('file')}</span><div><h3>${E(c.title)}</h3>${R.data.prefs.previews?`<p>${E(R.noteExcerpt(c))}</p>`:''}</div></button><div class="note-row-meta">${R.stage(c)}<time>${R.age(c.updated)}</time></div>${R.bookmark(c)}</article>`).join('')}</div>`:R.empty();
R.gallery=cards=>cards.length?`<div class="note-gallery">${cards.map((c,i)=>`<article class="note-tile tile-color-${i%4}"><div class="tile-top"><span>${E(R.folder(c.folder)?.name||'A loose thought')}</span>${R.bookmark(c)}</div><button class="tile-open" data-open="${E(c.id)}">${c.attachments.find(a=>a.type?.startsWith('image/'))?`<div class="tile-image"><img data-hydrate="${E(c.attachments.find(a=>a.type?.startsWith('image/')).id)}" alt="Attached to ${E(c.title)}"></div>`:''}<h3>${E(c.title)}</h3>${R.data.prefs.previews?`<p>${E(R.noteExcerpt(c))}</p>`:''}</button><div class="tile-bottom"><span>${R.noteTags(c)||R.stage(c)}</span><time>${R.age(c.updated)}</time></div></article>`).join('')}</div>`:R.empty();
R.board=cards=>`<div class="note-board" aria-label="Your board">${R.data.columns.map((col,i)=>{const notes=cards.filter(c=>c.status===col.id);return `<section class="note-lane" data-drop-status="${E(col.id)}" style="--column-color:${/^#[a-f\d]{6}$/i.test(col.color)?col.color:'#a9bda0'}"><header><span class="lane-dot"></span><h3>${E(col.name)}</h3><small>${notes.length}</small>${R.btn(I('plus'),'new','icon-button',`data-new-status="${E(col.id)}" aria-label="Leave a note in ${E(col.name)}"`)}</header><div class="lane-stack">${notes.map((c,n)=>`<article class="pin-card pin-${(i+n)%4}" draggable="true" data-drag-id="${E(c.id)}"><div class="pin-card-top">${R.noteTags(c)||`<span>${E(R.folder(c.folder)?.name||'A loose thought')}</span>`}${R.bookmark(c)}</div><button data-open="${E(c.id)}"><h3>${E(c.title)}</h3>${R.data.prefs.previews?`<p>${E(R.noteExcerpt(c))}</p>`:''}${R.next(c)?`<div class="pin-next"><span>Next time →</span><p>${E(R.next(c))}</p></div>`:''}</button><div class="pin-card-bottom"><time>${R.age(c.updated)}</time>${c.attachments.length?`<span>${I('link')}${c.attachments.length}</span>`:''}<select data-status-id="${E(c.id)}" aria-label="Move ${E(c.title)}">${R.data.columns.map(x=>`<option value="${E(x.id)}" ${c.status===x.id?'selected':''}>${E(x.name)}</option>`).join('')}</select></div></article>`).join('')}${R.btn(`${I('plus')}A new thought`,'new','lane-new',`data-new-status="${E(col.id)}"`)}</div></section>`;}).join('')}<button class="add-lane" data-action="customize" data-tab="board">${I('plus')}Make another space</button></div>`;
R.collection=(cards=R.cards())=>R.view()==='board'?R.board(cards):R.view()==='gallery'?R.gallery(cards):R.list(cards);
R.quickCapture=()=>`<form class="quick-capture" id="quick-capture">${I('plus')}<input name="thought" required maxlength="180" placeholder="Catch a thought before it goes…" aria-label="Quick note"><button type="submit" aria-label="Keep this thought">${I('arrow')}</button></form>`;
R.latest=()=>R.cards().find(c=>c.status!=='done')||R.cards()[0];
R.returnStrip=()=>{const c=R.latest();return c?`<button class="return-strip" data-open="${E(c.id)}"><span class="return-symbol">↳</span><div><small>Last time you were here</small><h3>${E(c.title)}</h3><p>${E(R.next(c)||R.noteExcerpt(c))}</p></div><span class="return-action">Pick up here ${I('arrow')}</span></button>`:'';};
R.files=c=>`<div class="reference-list">${c.files.map(f=>`<button data-reference="${E(f)}">${I('file')}<span>${E(f)}</span>${I('copy')}</button>`).join('')}${(c.links||'').split('\n').filter(Boolean).map(u=>{let safe=false;try{safe=['https:','http:'].includes(new URL(u).protocol);}catch{}return safe?`<a href="${E(u)}" target="_blank" rel="noopener noreferrer">${I('link')}<span>${E(u)}</span>↗</a>`:`<span>${E(u)}</span>`;}).join('')}</div>`;
R.noteContents=(c,inline=false)=>`<article class="reading-note"><div class="reading-overline"><span>${E(R.folder(c.folder)?.name||'A loose thought')}</span>${R.bookmark(c)}</div><h2 ${inline?'':'id="modal-title"'}>${E(c.title)}</h2><div class="reading-meta">${R.stage(c)}<time>${R.date(c.updated,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div>${inline?`<textarea class="inline-thought" data-inline-id="${E(c.id)}" aria-label="Your thoughts" placeholder="A little more room for the thought…">${E(c.body)}</textarea><small class="inline-save" id="inline-save">Your thoughts save as you write.</small>`:`<div class="reading-body">${R.prose(c.body||(!R.template(c.template).fields.length?'A little room for the thought to grow.':''))}</div>`}<div class="reading-prompts">${R.template(c.template).fields.filter(f=>R.value(c,f.id)!==''&&R.value(c,f.id)!==false).map(f=>`<section><span>${E(f.label)}</span><p>${E(R.value(c,f.id)===true?'Yes':R.value(c,f.id))}</p></section>`).join('')}</div>${R.extraAnswers(c).length?`<details class="earlier-layout"><summary>Kept from an earlier page layout</summary>${R.extraAnswers(c).map(a=>`<section><span>${E(a.label)}</span><p>${E(a.value===true?'Yes':a.value)}</p></section>`).join('')}</details>`:''}${c.attachments.length?`<div class="reading-attachments">${c.attachments.map(a=>`<button data-action="open-attachment" data-file-id="${E(a.id)}">${a.type?.startsWith('image/')?`<img data-hydrate="${E(a.id)}" alt="${E(a.name)}">`:I('file')}<span>${E(a.name)}</span></button>`).join('')}</div>`:''}${c.files.length||c.links||c.branch?`<details class="reading-context"><summary>${I('branch')}A few breadcrumbs back to the code</summary>${c.branch?`<code>${E(c.branch)}</code>`:''}${R.files(c)}<small>Saved references; the prototype is not connected to an editor.</small></details>`:''}<div class="reading-bottom">${R.btn(`${I('edit')}Keep writing`,'edit','button primary',`data-id="${E(c.id)}"`)}${R.btn(`${I('export')}Take a copy`,'export-card','quiet-button',`data-id="${E(c.id)}"`)}${R.btn(I(c.archived?'restore':'archive'),'archive-card','icon-button',`data-id="${E(c.id)}" aria-label="${c.archived?'Bring back':'Put aside'} this note"`)}</div><details class="earlier-thoughts"><summary>${I('clock')}Earlier thoughts<span>${c.history.length}</span></summary>${c.history.length?c.history.map(h=>`<article><time>${R.date(h.at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time><p>${E(h.body||h.tried||'A small change along the way.')}</p>${h.next?`<p><b>Next time:</b> ${E(h.next)}</p>`:''}${h.values?Object.entries(h.values).filter(([k,v])=>v!==''&&v!==false).map(([k,v])=>`<p>${E(v===true?'Yes':v)}</p>`).join(''):''}</article>`).join(''):'<p class="history-empty">As you leave checkpoints, the earlier thinking stays here.</p>'}</details></article>`;
R.studio=()=>`<div class="workspace studio">${R.sidebar()}<div class="workspace-body">${R.header()}<main class="studio-main" id="main"><div class="studio-heading"><div><span class="eyebrow">A PLACE TO KEEP GOING</span><h1>${E(R.scopeTitle())}<span>.</span></h1><p>${E(R.folder(R.ui.folder)?.description||R.data.projectDetails[R.ui.project]?.description||'A place for whatever you’re making.')}</p></div><div class="heading-actions">${R.ui.folder?R.btn(I('more'),'folder-options','icon-button',`data-id="${E(R.ui.folder)}" aria-label="Folder options"`):R.btn(`${I('folder')}New folder`,'new-folder','button secondary')}${R.newButton()}</div></div>${R.ui.scope==='all'&&!R.ui.query?R.returnStrip():''}${R.ui.scope==='all'&&!R.ui.query?R.folderCards():''}<section class="collection">${R.collectionHeader()}${R.collection()}</section><div class="workspace-end"><span>Make a little progress. Leave a little context.</span>${R.btn('Make this space yours ↗','customize','quiet-button')}</div></main></div></div>`;
R.folio=()=>`<div class="workspace folio">${R.sidebar()}<div class="workspace-body">${R.header()}<main id="main" class="folio-main"><div class="folio-heading"><div class="folio-volume"><span>YOUR PERSONAL LIBRARY</span><span>VOL. ${String(R.data.projects.indexOf(R.ui.project)+1).padStart(2,'0')}</span></div><h1>${R.ui.folder?E(R.scopeTitle()):'Room for<br><em>a thought.</em>'}</h1><div class="folio-heading-bottom"><p>${E(R.folder(R.ui.folder)?.description||R.data.projectDetails[R.ui.project]?.description)}</p>${R.newButton('Open a fresh page')}</div></div>${R.ui.scope==='all'&&!R.ui.query?R.folderCards():''}<section class="collection">${R.collectionHeader(R.ui.scope==='saved'?'The pages you kept close':'Pages from your workspace')}${R.collection()}</section><footer class="folio-footer"><span>Nothing here has to be finished.</span><span>Just worth remembering.</span></footer></main></div></div>`;
R.pinboard=()=>`<div class="workspace pinboard">${R.sidebar()}<div class="workspace-body">${R.header()}<main id="main" class="pinboard-main"><div class="pinboard-heading"><div><span class="eyebrow">A FEW THINGS ON YOUR MIND</span><h1>${R.ui.folder?E(R.scopeTitle()):'Let it take shape.'}</h1><p>Move things around. There’s no right way to arrange a thought.</p></div>${R.newButton('Pin a thought')}</div><div class="board-location"><div class="folder-chips"><button data-action="root" class="${!R.ui.folder?'active':''}">${I('grid')}All corners</button>${R.data.folders.filter(f=>f.project===R.ui.project&&!f.parent).map(f=>`<button data-folder="${E(f.id)}" class="${R.ui.folder===f.id?'active':''}">${I('folder')}${E(f.name)}</button>`).join('')}</div>${R.btn(`${I('settings')}Shape your board`,'customize','quiet-button','data-tab="board"')}</div><section class="collection">${R.collectionHeader('Your thoughts, with a little room')}${R.collection()}</section>${R.quickCapture()}<div class="pinboard-foot"><span>Drag notes between spaces, or use the move menu on a note.</span><span>Names, colors, and stages are all yours to change.</span></div></main></div></div>`;
R.journalEntries=()=>{const groups=new Map();R.cards().forEach(c=>{const day=R.date(c.updated,{day:'numeric',month:'long'});if(!groups.has(day))groups.set(day,[]);groups.get(day).push(c);});return [...groups].map(([day,notes])=>`<section class="almanac-day"><div class="day-heading"><span>${day}</span><i></i><small>${notes.length===1?'one little thought':notes.length+' little thoughts'}</small></div>${notes.map(c=>`<article class="almanac-entry"><div class="entry-mark"><span>${R.date(c.updated,{hour:'2-digit',minute:'2-digit'})}</span><i></i></div><div><div class="entry-top"><span>${E(R.folder(c.folder)?.name||'A loose thought')}</span>${R.bookmark(c)}</div><button class="entry-title" data-open="${E(c.id)}"><h2>${E(c.title)}</h2></button><div class="entry-prose">${R.prose(c.body||c.tried||'A thought waiting to unfold.')}</div>${R.next(c)?`<div class="entry-next"><span>Next time, perhaps →</span><p>${E(R.next(c))}</p></div>`:''}<div class="entry-footer">${R.noteTags(c)}${R.btn(`A little more to add ${I('arrow')}`,'edit','quiet-button',`data-id="${E(c.id)}"`)}</div></div></article>`).join('')}</section>`).join('')||R.empty();};
R.almanac=()=>`<div class="almanac"><header class="almanac-header">${R.logo()}<span>A WORKING NOTEBOOK</span><div>${R.projectSelect()}${R.btn(I('settings'),'customize','icon-button','aria-label="Make it yours"')}${R.newButton('Write a little')}</div></header><main id="main" class="almanac-main"><aside class="almanac-index"><span class="eyebrow">BETWEEN THESE PAGES</span><nav>${[['all','Everything'],['saved','Kept close'],['archive','Put aside']].map(([key,name])=>`<button data-scope="${key}" class="${R.ui.scope===key&&!R.ui.folder?'active':''}">${name}</button>`).join('')}</nav><div class="almanac-folders">${R.folderTree()}</div>${R.btn(`${I('plus')}A new chapter`,'new-folder','quiet-button')}<div class="almanac-margin-note"><span>For the things<br>you nearly forgot.</span><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M15 10c65-10 75 45 35 50S20 30 65 45s15 30 5 40m-7-5 7 5 7-8"/></svg></div>${R.btn(`${I('export')}Take a copy`,'backup','quiet-button')}</aside><section class="almanac-pages"><div class="almanac-heading"><span class="eyebrow">${E(R.scopeTitle()).toUpperCase()} / AN ONGOING CONVERSATION</span><h1>A note to<br><em>tomorrow.</em></h1><p>What happened. What mattered. What you might try next.</p></div><div class="almanac-search">${R.search('Find a little piece of the story…')}${R.btn(`${I('folder')}Your corners`,'browse-folders','quiet-button')}</div>${R.quickCapture()}${R.view()==='list'||R.view()==='gallery'||R.view()==='board'?`<section class="collection">${R.collectionHeader('Pages, your way')}${R.collection()}</section>`:R.journalEntries()}<div class="almanac-end"><span>That’s the story so far.</span>${R.newButton('Leave the next thought')}</div></section><aside class="almanac-annotation"><span>PERSONAL NOTES</span><p>${R.date(Date.now(),{month:'long'})}<br><em>${R.date(Date.now(),{year:'numeric'})}</em></p><div class="annotation-rule"></div><span>Come back<br>as you are.</span></aside></main></div>`;
R.pocket=()=>{const cards=R.cards(),current=R.current();return `<div class="pocket"><aside class="pocket-rail">${R.logo()}${R.btn(I('grid'),'root','rail-button','aria-label="Everything in this project"')}${R.btn(I('pin'),'saved','rail-button','aria-label="Kept close"')}${R.btn(I('folder'),'toggle-sidebar','rail-button','aria-label="Browse folders"')}${R.btn(I('plus'),'new','rail-button rail-new','aria-label="Leave a note"')}<div>${R.btn(I('archive'),'archive-scope','rail-button','aria-label="Notes put aside"')}${R.btn(I('settings'),'customize','rail-button','aria-label="Make it yours"')}</div></aside>${R.ui.sideOpen?`<div class="pocket-folder-drawer">${R.sidebar()}</div>`:''}<section class="pocket-inbox"><header>${R.projectSelect()}${R.btn(I('more'),'project-options','icon-button','aria-label="Project options"')}</header><div class="pocket-inbox-heading"><div><h1>${R.ui.folder?E(R.scopeTitle()):R.ui.scope==='saved'?'Kept close':R.ui.scope==='archive'?'Put aside':'A few open thoughts'}</h1><span>${cards.length} ${cards.length===1?'note':'notes'}</span></div>${R.btn(I('plus'),'new','icon-button','aria-label="New note"')}</div>${R.search()}<div class="pocket-crumb">${R.ui.folder?`<button data-action="root">All notes</button><span>/</span><span>${E(R.folder(R.ui.folder)?.name)}</span>`:R.btn(`${I('folder')}Your little corners`,'toggle-sidebar','quiet-button')}</div><nav class="pocket-note-list" aria-label="Notes">${cards.map(c=>`<button data-select="${E(c.id)}" class="${current?.id===c.id?'active':''}"><div><span>${E(R.folder(c.folder)?.name||'Unfiled')}</span><time>${R.age(c.updated)}</time></div><h2>${E(c.title)}</h2>${R.data.prefs.previews?`<p>${E(R.noteExcerpt(c))}</p>`:''}${R.stage(c)}</button>`).join('')||'<p class="pocket-empty">A little breathing room. Start a fresh note whenever you like.</p>'}</nav><div class="pocket-inbox-foot"><i></i>Yours, in this browser.</div></section><main class="pocket-reader" id="main"><header><span>${I('file')}A PLACE TO THINK</span>${R.btn(I('info'),'research','icon-button','aria-label="The idea behind Relay"')}</header>${current?R.noteContents(current,true):R.empty()}</main></div>`;};
R.switcher=()=>`<span class="switcher-label">FIND YOUR FEELING</span><div class="switcher-options" role="group" aria-label="Five prototype directions">${R.modes.map((m,i)=>`<button data-mode="${i+1}" class="${R.mode===i+1?'active':''}" aria-label="Prototype ${i+1}: ${m.name}" aria-pressed="${R.mode===i+1}"><span>${i+1}</span><small>${m.name}</small></button>`).join('')}</div><span class="switcher-caption">${R.modes[R.mode-1].description}</span>${R.btn(I('info'),'compare','switcher-help','aria-label="About these five directions"')}`;
R.hydrate=async()=>{await R.filesReady;for(const img of document.querySelectorAll('[data-hydrate]')){const f=await R.getFile(img.dataset.hydrate);if(f&&/^data:image\/(png|jpeg|gif|webp|avif|bmp);base64,/i.test(f.src))img.src=f.src;}};
R.render=()=>{const active=document.activeElement,isSearch=active?.hasAttribute('data-search'),position=isSearch?active.selectionStart:null;document.body.dataset.prototype=R.mode;document.body.dataset.density=R.data.prefs.density;document.documentElement.style.setProperty('--personal-accent',/^#[a-f\d]{6}$/i.test(R.data.prefs.accent)?R.data.prefs.accent:'');document.querySelector('#app').innerHTML=[null,R.studio,R.folio,R.pinboard,R.almanac,R.pocket][R.mode]();document.querySelector('#prototype-switcher').innerHTML=R.switcher();if(isSearch){const input=document.querySelector('[data-search]');input?.focus();input?.setSelectionRange(position,position);}R.hydrate();};
